"""2026-10-16 ET. Approved bounded source/metadata staging only; no reader invocation."""
import base64, hashlib, json, os, stat, sys
from pathlib import Path
from datetime import datetime, timezone
PAYLOAD = json.loads(base64.b64decode(''))
root = Path(PAYLOAD['fresh_raw'])
assert str(root) == '/data/yanruj/EvolveSWDB_runs/probata-resume-20261016-t28-trace-cold-04af74c1-v2'
assert root.parent.resolve(strict=True) == root.parent and not os.path.lexists(root)
assert PAYLOAD['source_commit'] == '04af74c121a733589fbe1a2087ad602deaef598b'
assert PAYLOAD['count'] == len(PAYLOAD['files']) == 17
assert PAYLOAD['bytes'] == sum(row['bytes'] for row in PAYLOAD['files'].values()) <= 1048576
contents = {}
for name, row in PAYLOAD['files'].items():
    assert Path(name).name == name and name not in ('', '.', '..')
    data = base64.b64decode(row['content_base64'], validate=True)
    assert len(data) == row['bytes'] and hashlib.sha256(data).hexdigest() == row['sha256']
    contents[name] = data
manifest = json.loads(contents['trace-cold-control-manifest-v2.json'])
assert manifest['expected_control_basenames'] == sorted(contents)
assert manifest['payload_file_count'] == 16 and manifest['manifest_self_listed'] is False
for name, row in manifest['payload_files'].items():
    assert row['path'] == str(root / 'control' / name)
    assert {key: row[key] for key in ('bytes', 'sha256')} == {key: PAYLOAD['files'][name][key] for key in ('bytes', 'sha256')}
space = os.statvfs('/data'); assert space.f_bavail * space.f_frsize > 2097152
def deny(event, arguments):
    if event.startswith(('subprocess.', 'os.exec', 'os.spawn', 'os.posix_spawn', 'socket.', 'ctypes.dlopen')) or event in {'os.system','os.fork','os.forkpty','os.remove','os.rename','os.rmdir','os.symlink','os.link','os.truncate'}:
        raise RuntimeError('staging refuses ' + event)
sys.addaudithook(deny)
root.mkdir(mode=0o700); control = root / 'control'; control.mkdir(mode=0o700)
for name, data in contents.items():
    descriptor = os.open(control / name, os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, 'O_NOFOLLOW', 0), 0o444)
    with os.fdopen(descriptor, 'wb') as stream:
        stream.write(data); stream.flush(); os.fsync(stream.fileno())
assert {path.name for path in root.iterdir()} == {'control'}
assert {path.name for path in control.iterdir()} == set(contents)
after = {}
for name in sorted(contents):
    path = control / name; before = path.lstat(); assert stat.S_ISREG(before.st_mode)
    data = path.read_bytes(); after_stat = path.lstat()
    assert (before.st_ino,before.st_size,before.st_mtime_ns,before.st_ctime_ns) == (after_stat.st_ino,after_stat.st_size,after_stat.st_mtime_ns,after_stat.st_ctime_ns)
    row = {'bytes': len(data), 'sha256': hashlib.sha256(data).hexdigest()}
    assert row == {key: PAYLOAD['files'][name][key] for key in ('bytes','sha256')}
    after[name] = {'path': str(path), **row}
assert not os.path.lexists(root / 'reader-source-cache') and not os.path.lexists(root / 'cache')
leases = {}
for name in ('mbit10-evaluation','mbit10-evaluation-node0','mbit10-evaluation-node1'):
    value = json.loads((Path('/data1/yanruj/lact-host-lease') / (name + '.meta.json')).read_bytes())
    leases[name] = {'state': value['state'], 'generation': value['lease']['generation']}
print(json.dumps({'date':'2026-10-16 ET','staged_utc':datetime.now(timezone.utc).isoformat(),'fresh_raw':str(root),'source_commit':PAYLOAD['source_commit'],'control_files':after,'control_file_count':len(after),'control_total_bytes':sum(row['bytes'] for row in after.values()),'point_in_time_lease_metadata':leases,'reader_source_cache_absent':True,'outer_cache_absent':True,'reader_executed':False,'scientific_execution':False,'scope':'bounded exact source/metadata files staged only; independent final invocation review and root admission remain required'},indent=2,sort_keys=True))
